import random


class TwentyFourPointGame:
    SENTINEL = -100
    TARGET_SUM = 24

    def __init__(self) -> None:
        self._nums = []

    def _generate_cards(self):
        for _ in range(4):
            self._nums.append(random.randint(1, 9))
        assert len(self._nums) == 4

    def get_my_cards(self):
        self._nums = []
        self._generate_cards()
        return self._nums

    def answer(self, expression):
        if expression == 'pass':
            return self.get_my_cards()
        if self._are_all_numbers_valid(expression):
            if self._are_all_numbers_used_once(expression):
                return self.evaluate_expression(expression)
        return False

    def _are_all_numbers_valid(self, expression):
        for c in expression:
            if c.isdigit():
                num = int(c)
                if num not in self._nums:
                    return False
        return True

    def _are_all_numbers_used_once(self, expression):
        nums_used = self._count_number_occurrences(expression)
        return self._verify_each_number_used_once(nums_used)

    def _count_number_occurrences(self, expression):
        statistic = {}
        for c in expression:
            if c.isdigit() and int(c) in self._nums:
                statistic[c] = statistic.get(c, 0) + 1
        return statistic

    def _verify_each_number_used_once(self, nums_used):
        for num in self._nums:
            key = str(num)
            if key in nums_used:
                if nums_used[key] <= 0:
                    return False
                nums_used[key] -= 1
            else:
                return False
        return all(count == self.SENTINEL or count == 0 for count in nums_used.values())

    def evaluate_expression(self, expression):
        try:
            return eval(expression) == self.TARGET_SUM
        except Exception:
            return False
